/* The generated program owns its native scalar runtime; the compiler DLL is build-time only. */
#include "internal.h"

void gcs_emit_runtime(gcs_compilation* c) {
    static const char runtime[] =
        "/* Generated by greencsharp: checked C# AST lowered to native C. */\n"
        "#include <stdint.h>\n#include <stdbool.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <inttypes.h>\n\n"
        "typedef int32_t i32;\ntypedef uint32_t u32;\n\n"
        "typedef struct {\n    i32 count;\n    char** values;\n} gcs_arguments;\n\n"
        "static inline const char* gcs_argument(gcs_arguments args, i32 index) {\n"
        "    if (index < 0 || index >= args.count) {\n"
        "        fputs(\"greencsharp: argument index out of range\\n\", stderr);\n\n        exit(1);\n    }\n\n"
        "    return args.values[index];\n}\n\n"
        "static inline i32 gcs_bits(u32 value) {\n    i32 result;\n    memcpy(&result, &value, sizeof(result));\n\n    return result;\n}\n\n"
        "static inline i32 gcs_add(i32 a, i32 b) {\n    return gcs_bits((u32)a + (u32)b);\n}\n\n"
        "static inline i32 gcs_subtract(i32 a, i32 b) {\n    return gcs_bits((u32)a - (u32)b);\n}\n\n"
        "static inline i32 gcs_multiply(i32 a, i32 b) {\n    return gcs_bits((u32)a * (u32)b);\n}\n\n"
        "static inline void gcs_arithmetic_error(void) {\n    fputs(\"greencsharp: integer division error\\n\", stderr);\n\n    exit(1);\n}\n\n"
        "static inline i32 gcs_divide(i32 a, i32 b) {\n"
        "    if (!b || (a == INT32_MIN && b == -1)) {\n        gcs_arithmetic_error();\n    }\n\n"
        "    return a / b;\n}\n\n"
        "static inline i32 gcs_remainder(i32 a, i32 b) {\n"
        "    if (!b) {\n        gcs_arithmetic_error();\n    }\n\n"
        "    if (a == INT32_MIN && b == -1) { return 0; }\n\n    return a % b;\n}\n\n"
        "static inline void gcs_write_int(i32 value, bool line) {\n    printf(\"%\" PRId32, value);\n\n"
        "    if (line) { fputc('\\n', stdout); }\n}\n\n"
        "static inline void gcs_write_bool(bool value, bool line) {\n    fputs(value ? \"True\" : \"False\", stdout);\n\n"
        "    if (line) { fputc('\\n', stdout); }\n}\n\n"
        "static inline void gcs_write_string(const char* value, bool line) {\n    fputs(value, stdout);\n\n"
        "    if (line) { fputc('\\n', stdout); }\n}\n\n";
    gcs_append(c, &c->program, "%s", runtime);
}
